package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.HashSet;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Retained summary consistency with the byte-pinned original request, runtime and per-case receipts. */
final class HifiasmResultConsistency {
    private HifiasmResultConsistency(){ }
    static void verify(Path out)throws IOException{
        var report=GseapyExecutionRuntime.read(out.resolve("COMPLETED.json"),33554432);var request=GseapyExecutionRuntime.read(out.resolve("request.original.json"),16777216);var runtime=GseapyExecutionRuntime.read(out.resolve("runtime.original.json"),33554432);
        require(text(report.get("edition")).equals(text(request.get("edition")))&&report.get("edition").equals(runtime.get("edition")),"Retained hifiasm summary edition differs from its original request/runtime");require(text(report.get("commit")).equals(text(runtime.get("commit")))&&text(report.get("commit")).matches("[0-9a-f]{40}"),"Retained hifiasm summary commit differs from its original runtime");require("PASS_BOUND_ORIGINAL_HIFIASM_RUNTIME_ONLY".equals(runtime.get("status"))&&Boolean.FALSE.equals(runtime.get("source_namespace_patched"))&&Boolean.FALSE.equals(runtime.get("analysis_installed_software")),"Retained original hifiasm runtime was not admitted unchanged");require(Boolean.TRUE.equals(report.get("structural_graph_validation_only"))&&Boolean.FALSE.equals(report.get("biological_or_paper_reproduction_certified"))&&!report.containsKey("error")&&!report.containsKey("error_details"),"Retained hifiasm success contains an error or an unsupported biological certification claim");
        var planned=list(request.get("analyses"));var completed=list(report.get("analyses"));require(planned.size()==completed.size()&&!planned.isEmpty()&&planned.size()<=32&&completed.equals(list(report.get("earlier_cases_are_provisional_unless_entire_receipt_passes"))),"Retained hifiasm complete analysis populations disagree");var identities=new HashSet<String>();
        for(int i=0;i<planned.size();i++){
            var original=object(planned.get(i));var summary=object(completed.get(i));String id=text(original.get("id"));require(id.matches("[A-Za-z][A-Za-z0-9_.-]{0,63}")&&identities.add(id)&&id.equals(summary.get("id"))&&text(original.get("mode")).equals(summary.get("mode")),"Retained hifiasm analysis identity/order/mode differs from its original request");Path home=out.resolve("analyses").resolve(id);var provisional=GseapyExecutionRuntime.read(home.resolve("PROVISIONAL.json"),1048576);require(summary.equals(provisional)&&"PROVISIONAL_ORIGINAL_ASSEMBLY_AND_NATIVE_GRAPH_AUDIT_ONLY".equals(summary.get("status"))&&Boolean.FALSE.equals(summary.get("analysis_admitted"))&&Boolean.FALSE.equals(summary.get("source_namespace_patched"))&&integer(summary.get("original_exit_code"),0,0)==0,"Retained case summary differs from its original subordinate receipt");
            var audit=list(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(home.resolve("graph-audit.json"),33554432)),33554432,2000000));require(audit.size()==integer(summary.get("graph_views"),1,1000000),"Retained complete graph count differs from its native audit");long bases=0;var graphs=new HashSet<String>();
            for(Object raw:audit){var graph=object(raw);String name=NextflowFiles.member(text(graph.get("graph")));require(name.endsWith(".gfa")&&graphs.add(name),"Retained original graph identity is invalid or duplicated");var fasta=object(graph.get("fasta"));var statistics=object(graph.get("statistics"));long sequenceBases=integer(fasta.get("sequenceBases"),0,Long.MAX_VALUE);require(sequenceBases==integer(statistics.get("sequenceBases"),0,Long.MAX_VALUE),"Retained native FASTA and source graph base counts disagree");try{bases=Math.addExact(bases,sequenceBases);}catch(ArithmeticException invalid){throw new IOException("Retained complete graph base total overflows its exact domain",invalid);}}
            require(bases==integer(summary.get("sequence_bases_across_graph_views"),1,Long.MAX_VALUE),"Retained case base total differs from its complete graph family");var command=list(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(home.resolve("command.json"),1048576)),1048576,100000));var process=GseapyExecutionRuntime.read(home.resolve("process/process.json"),16777216);var actual=list(process.get("command"));require(!command.isEmpty()&&text(command.get(0)).equals(text(runtime.get("binary")))&&actual.size()>=command.size()&&actual.subList(actual.size()-command.size(),actual.size()).equals(command),"Retained original process command differs from its exact runtime/declared invocation");
        }
    }
}
